# Expression parser: supports arithmetic, logical, comparison, between, in, like
def parse_expr(p):
    return parse_or(p)


def parse_or(p):
    left = parse_and(p)
    while p.match_keyword('or'):
        right = parse_and(p)
        left = AST('or', None, [left, right])
    return left


def parse_and(p):
    left = parse_not(p)
    while p.match_keyword('and'):
        right = parse_not(p)
        left = AST('and', None, [left, right])
    return left


def parse_not(p):
    if p.match_keyword('not'):
        operand = parse_not(p)
        return AST('not', None, [operand])
    return parse_comparison(p)


def parse_comparison(p):
    left = parse_additive(p)
    # between special-case
    if p.match_keyword('between'):
        a = parse_additive(p)
        if not p.match_keyword('and'):
            raise ParseError("expected 'and' in between")
        b = parse_additive(p)
        return AST('between', None, [left, a, b])
    if p.match_keyword('in'):
        if p.eof() or p.peek().kind != 'lparen':
            raise ParseError("expected '(' after 'in'")
        p.consume()
        items = []
        if p.peek() and p.peek().kind != 'rparen':
            items.append(parse_expr(p))
            while not p.eof() and p.peek().kind == 'comma':
                p.consume()
                items.append(parse_expr(p))
        if p.eof() or p.peek().kind != 'rparen':
            raise ParseError("expected ')' after 'in'")
        p.consume()
        return AST('in', None, [left] + items)
    if p.match_keyword('like'):
        right = parse_additive(p)
        return AST('cmp', 'like', [left, right])
    if p.match_keyword('notlike'):
        right = parse_additive(p)
        return AST('cmp', 'notlike', [left, right])
    # operator-based comparisons
    if not p.eof():
        t = p.peek()
        if t.kind == 'op' and t.value in OP_ALIASES:
            p.consume()
            right = parse_additive(p)
            return AST('cmp', OP_ALIASES[t.value], [left, right])
        if t.kind == 'ident' and t.value.lower() in OP_ALIASES and t.value.lower() not in ('in', 'between', 'like', 'notlike', 'exists'):
            p.consume()
            right = parse_additive(p)
            return AST('cmp', OP_ALIASES[t.value.lower()], [left, right])
    return left


def parse_additive(p):
    left = parse_multiplicative(p)
    while not p.eof():
        t = p.peek()
        if t.kind == 'op' and t.value in ('+', '-'):
            p.consume()
            right = parse_multiplicative(p)
            left = AST('arith', t.value, [left, right])
        elif t.kind == 'ident' and t.value.lower() in ('plus', 'minus'):
            op = '+' if t.value.lower() == 'plus' else '-'
            p.consume()
            right = parse_multiplicative(p)
            left = AST('arith', op, [left, right])
        else:
            break
    return left


def parse_multiplicative(p):
    left = parse_unary(p)
    while not p.eof():
        t = p.peek()
        if t.kind == 'op' and t.value in ('*', '/', '%'):
            p.consume()
            right = parse_unary(p)
            left = AST('arith', t.value, [left, right])
        elif t.kind == 'ident' and t.value.lower() in ('mul', 'div', 'mod'):
            mp = {'mul': '*', 'div': '/', 'mod': '%'}
            op = mp[t.value.lower()]
            p.consume()
            right = parse_unary(p)
            left = AST('arith', op, [left, right])
        else:
            break
    return left


def parse_unary(p):
    t = p.peek()
    if t is not None and t.kind == 'op' and t.value == '-':
        p.consume()
        operand = parse_unary(p)
        return AST('arith', '-', [AST('number', 0), operand])
    if t is not None and t.kind == 'op' and t.value == '+':
        p.consume()
        return parse_unary(p)
    return parse_primary(p)


def parse_primary(p):
    if p.eof():
        raise ParseError("Error parsing expression, expecting string")
    t = p.peek()
    if t.kind == 'lparen':
        p.consume()
        # Check if this is a subquery (starts with 'select')
        if not p.eof() and p.peek().kind == 'ident' and p.peek().value.lower() == 'select':
            # Not fully implementing subqueries here; parse best-effort
            # Consume until matching close paren
            depth = 1
            collected = []
            while not p.eof() and depth > 0:
                tok = p.consume()
                if tok.kind == 'lparen':
                    depth += 1
                    collected.append(tok)
                elif tok.kind == 'rparen':
                    depth -= 1
                    if depth > 0:
                        collected.append(tok)
                else:
                    collected.append(tok)
            return AST('subquery', collected)
        expr = parse_expr(p)
        if p.eof() or p.peek().kind != 'rparen':
            raise ParseError("expected ')'")
        p.consume()
        return expr
    if t.kind == 'number':
        p.consume()
        return AST('number', t.value)
    if t.kind == 'string':
        p.consume()
        return AST('string', t.value)
    if t.kind == 'ident':
        name = t.value
        low = name.lower()
        if low in ('true', 'false'):
            p.consume()
            return AST('bool', low == 'true')
        if low == 'null':
            p.consume()
            return AST('null')
        # function call?
        if p.peek(1) is not None and p.peek(1).kind == 'lparen' and low in FUNCTIONS_LOWER:
            p.consume()
            p.consume()  # (
            args = []
            if p.peek() and p.peek().kind != 'rparen':
                args.append(parse_expr(p))
                while not p.eof() and p.peek().kind == 'comma':
                    p.consume()
                    args.append(parse_expr(p))
            if p.eof() or p.peek().kind != 'rparen':
                raise ParseError("expected ')'")
            p.consume()
            if low == 'count' and len(args) == 1 and args[0].kind == 'ident' and args[0].value == '*':
                args = []
            return AST('call', low, args)
        # no-arg function (like current_user, pi)
        if low in ('current_uid', 'current_user', 'current_gid', 'current_group', 'pi', 'random', 'rand'):
            p.consume()
            return AST('call', low, [])
        # column or identifier
        p.consume()
        return AST('ident', name)
    if t.kind == 'op' and t.value == '*':
        p.consume()
        return AST('ident', '*')
    # fallback
    p.consume()
    return AST('string', t.value if t.value is not None else '')


# ---------------------------------------------------------------------------
# Evaluator
# ---------------------------------------------------------------------------

def size_unit_bytes(unit):
    unit = unit.lower()
    mapping = {
        'b': 1,
        'k': 1024, 'kb': 1024, 'kib': 1024,
        'm': 1024**2, 'mb': 1024**2, 'mib': 1024**2,
        'g': 1024**3, 'gb': 1024**3, 'gib': 1024**3,
        't': 1024**4, 'tb': 1024**4, 'tib': 1024**4,
        'p': 1024**5, 'pb': 1024**5, 'pib': 1024**5,
    }
    return mapping.get(unit, 1)


def parse_number_token(val):
    """Parse a tokenizer number value, possibly with unit suffix '@unit'."""
    if '@' in val:
        num, unit = val.split('@', 1)
        try:
            base = float(num) if '.' in num else int(num)
        except Exception:
            return 0
        return int(base * size_unit_bytes(unit)) if isinstance(base, int) else base * size_unit_bytes(unit)
    try:
        if '.' in val:
            return float(val)
        return int(val)
    except Exception:
        return 0


def mode_string(st_mode):
    if stat.S_ISDIR(st_mode):
        t = 'd'
    elif stat.S_ISLNK(st_mode):
        t = 'l'
    elif stat.S_ISCHR(st_mode):
        t = 'c'
    elif stat.S_ISBLK(st_mode):
        t = 'b'
    elif stat.S_ISFIFO(st_mode):
        t = 'p'
    elif stat.S_ISSOCK(st_mode):
        t = 's'
    else:
        t = '-'
    perms = ''
    for who, shift in (('u', 6), ('g', 3), ('o', 0)):
        r = 'r' if st_mode & (0o4 << shift) else '-'
        w = 'w' if st_mode & (0o2 << shift) else '-'
        x = 'x' if st_mode & (0o1 << shift) else '-'
        if who == 'u' and (st_mode & stat.S_ISUID):
            x = 's' if x == 'x' else 'S'
        if who == 'g' and (st_mode & stat.S_ISGID):
            x = 's' if x == 'x' else 'S'
        if who == 'o' and (st_mode & stat.S_ISVTX):
            x = 't' if x == 'x' else 'T'
        perms += r + w + x
    return t + perms


def human_size(n):
    try:
        n = int(n)
    except Exception:
        return str(n)
    units = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB']
    i = 0
    v = float(n)
    while v >= 1024 and i + 1 < len(units):
        v /= 1024
        i += 1
    if i == 0:
        return "%dB" % n
    if v == int(v):
        return "%d%s" % (int(v), units[i])
    return "%.2f%s" % (v, units[i])


def fmt_timestamp(t):
    try:
        return datetime.fromtimestamp(int(t)).strftime('%Y-%m-%d %H:%M:%S')
    except Exception:
        return ''
