# Expression parser: supports arithmetic, logical, comparison, between, in, like
def parse_expr(p):
    return parse_or(p)


def parse_or(p):
    left = parse_and(p)
    while p.match_keyword('or'):
        right = parse_and(p)
        left = AST('or', None, [left, right])
    return left


def parse_and(p):
    left = parse_not(p)
    while p.match_keyword('and'):
        right = parse_not(p)
        left = AST('and', None, [left, right])
    return left


def parse_not(p):
    if p.match_keyword('not'):
        operand = parse_not(p)
        return AST('not', None, [operand])
    return parse_comparison(p)


def parse_comparison(p):
    left = parse_additive(p)
    # between special-case
    if p.match_keyword('between'):
        a = parse_additive(p)
        if not p.match_keyword('and'):
            raise ParseError("expected 'and' in between")
        b = parse_additive(p)
        return AST('between', None, [left, a, b])
    if p.match_keyword('in'):
        if p.eof() or p.peek().kind != 'lparen':
            raise ParseError("expected '(' after 'in'")
        p.consume()
