                items.append(parse_expr(p))
        if p.eof() or p.peek().kind != 'rparen':
            raise ParseError("expected ')' after 'in'")
        p.consume()
        return AST('in', None, [left] + items)
    if p.match_keyword('like'):
        right = parse_additive(p)
        return AST('cmp', 'like', [left, right])
    if p.match_keyword('notlike'):
        right = parse_additive(p)
        return AST('cmp', 'notlike', [left, right])
    # operator-based comparisons
    if not p.eof():
        t = p.peek()
        if t.kind == 'op' and t.value in OP_ALIASES:
