def get_column(record, col):
    """Compute one of the known file columns for `record`."""
    path = record['path']
    root = record['root']
    abspath = record['abspath']
    st = record.get('stat')
    lst = record.get('lstat') or st

    if col == 'name':
        return os.path.basename(path) if path != '' else os.path.basename(abspath)
    if col == 'filename':
        name = os.path.basename(path) if path else os.path.basename(abspath)
        if '.' in name:
            return name.rsplit('.', 1)[0]
        return name
    if col == 'ext':
        name = os.path.basename(path) if path else os.path.basename(abspath)
        if '.' in name and not name.startswith('.'):
            return name.rsplit('.', 1)[1]
        return ''
    if col == 'path':
        return path
    if col == 'abspath':
        return abspath
    if col == 'dir':
        d = os.path.dirname(path)
        return d
    if col == 'absdir':
        return os.path.dirname(abspath)
    if col == 'size':
        return st.st_size if st else 0
    if col == 'fsize':
        return human_size(st.st_size) if st else '0B'
    if col == 'uid':
        return st.st_uid if st else 0
    if col == 'gid':
        return st.st_gid if st else 0
    if col == 'user':
        if st is None:
            return ''
        try:
            return pwd.getpwuid(st.st_uid).pw_name
        except Exception:
            return str(st.st_uid)
    if col == 'group':
        if st is None:
            return ''
        try:
            return grp.getgrgid(st.st_gid).gr_name
        except Exception:
            return str(st.st_gid)
    if col == 'created':
        if st is None:
            return ''
        # Linux: use st_ctime as fallback
        t = getattr(st, 'st_birthtime', None)
        if t is None:
            t = st.st_ctime
        return fmt_timestamp(t)
    if col == 'accessed':
        return fmt_timestamp(st.st_atime) if st else ''
    if col == 'modified':
        return fmt_timestamp(st.st_mtime) if st else ''
    if col == 'atime':
        return int(st.st_atime) if st else 0
    if col == 'mtime':
        return int(st.st_mtime) if st else 0
    if col == 'ctime':
        return int(st.st_ctime) if st else 0
    if col == 'mode':
        return mode_string(st.st_mode) if st else ''
    if col == 'is_dir':
        return bool(st and stat.S_ISDIR(st.st_mode))
    if col == 'is_file':
        return bool(st and stat.S_ISREG(st.st_mode))
    if col == 'is_symlink':
        return bool(lst and stat.S_ISLNK(lst.st_mode))
    if col == 'is_pipe':
        return bool(st and stat.S_ISFIFO(st.st_mode))
    if col == 'is_char':
        return bool(st and stat.S_ISCHR(st.st_mode))
    if col == 'is_block':
        return bool(st and stat.S_ISBLK(st.st_mode))
    if col == 'is_socket':
        return bool(st and stat.S_ISSOCK(st.st_mode))
    if col == 'is_hidden':
        name = os.path.basename(path) if path else os.path.basename(abspath)
        return name.startswith('.')
    if col == 'is_empty':
        if st is None:
            return False
        if stat.S_ISDIR(st.st_mode):
            try:
                return len(os.listdir(abspath)) == 0
            except Exception:
                return False
        return st.st_size == 0
    if col == 'device':
        return st.st_dev if st else 0
    if col == 'rdev':
        return getattr(st, 'st_rdev', 0) if st else 0
    if col == 'inode':
        return st.st_ino if st else 0
    if col == 'blocks':
        return getattr(st, 'st_blocks', 0) if st else 0
    if col == 'hardlinks':
        return st.st_nlink if st else 0
    if col in ('user_read', 'user_write', 'user_exec'):
        if st is None:
            return False
        m = {'user_read': stat.S_IRUSR, 'user_write': stat.S_IWUSR, 'user_exec': stat.S_IXUSR}[col]
        return bool(st.st_mode & m)
    if col == 'user_all':
        if st is None: return False
        return bool(st.st_mode & stat.S_IRUSR) and bool(st.st_mode & stat.S_IWUSR) and bool(st.st_mode & stat.S_IXUSR)
    if col in ('group_read', 'group_write', 'group_exec'):
        if st is None:
            return False
        m = {'group_read': stat.S_IRGRP, 'group_write': stat.S_IWGRP, 'group_exec': stat.S_IXGRP}[col]
        return bool(st.st_mode & m)
    if col == 'group_all':
        if st is None: return False
        return bool(st.st_mode & stat.S_IRGRP) and bool(st.st_mode & stat.S_IWGRP) and bool(st.st_mode & stat.S_IXGRP)
    if col in ('other_read', 'other_write', 'other_exec'):
        if st is None:
            return False
        m = {'other_read': stat.S_IROTH, 'other_write': stat.S_IWOTH, 'other_exec': stat.S_IXOTH}[col]
        return bool(st.st_mode & m)
    if col == 'other_all':
        if st is None: return False
        return bool(st.st_mode & stat.S_IROTH) and bool(st.st_mode & stat.S_IWOTH) and bool(st.st_mode & stat.S_IXOTH)
    if col == 'suid':
        return bool(st.st_mode & stat.S_ISUID) if st else False
    if col == 'sgid':
        return bool(st.st_mode & stat.S_ISGID) if st else False
    if col == 'sticky':
        return bool(st.st_mode & stat.S_ISVTX) if st else False
    if col == 'is_shebang':
        if st is None or not stat.S_ISREG(st.st_mode):
            return False
        try:
            with open(abspath, 'rb') as f:
                return f.read(2) == b'#!'
        except Exception:
            return False
    if col in ('is_archive', 'is_audio', 'is_book', 'is_doc', 'is_font',
               'is_image', 'is_source', 'is_video'):
        ext = get_column(record, 'ext').lower()
        m = {
            'is_archive': ARCHIVE_EXTS, 'is_audio': AUDIO_EXTS, 'is_book': BOOK_EXTS,
            'is_doc': DOC_EXTS, 'is_font': FONT_EXTS, 'is_image': IMAGE_EXTS,
            'is_source': SOURCE_EXTS, 'is_video': VIDEO_EXTS,
        }[col]
        return ext in m
    if col == 'is_binary':
        if st is None or not stat.S_ISREG(st.st_mode):
            return False
        try:
            with open(abspath, 'rb') as f:
                data = f.read(4096)
            return b'\x00' in data
        except Exception:
            return False
    if col == 'is_text':
        return (stat.S_ISREG(st.st_mode) if st else False) and not get_column(record, 'is_binary')
    if col == 'mime':
        return ''
    if col == 'line_count':
        if st is None or not stat.S_ISREG(st.st_mode):
            return 0
        try:
            cnt = 0
            with open(abspath, 'rb') as f:
                for _ in f:
                    cnt += 1
            return cnt
        except Exception:
            return 0
    if col == 'width' or col == 'height' or col == 'duration':
        return 0
    if col == 'sha1':
        return file_hash(abspath, 'sha1') if st and stat.S_ISREG(st.st_mode) else ''
    if col == 'sha256':
        return file_hash(abspath, 'sha256') if st and stat.S_ISREG(st.st_mode) else ''
    if col == 'sha512':
        return file_hash(abspath, 'sha512') if st and stat.S_ISREG(st.st_mode) else ''
    if col == 'sha3':
        return file_hash(abspath, 'sha3_512') if st and stat.S_ISREG(st.st_mode) else ''
    return None


def file_hash(path, algo):
    try:
        h = hashlib.new(algo)
        with open(path, 'rb') as f:
            while True:
                chunk = f.read(1 << 16)
                if not chunk:
                    break
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return ''
