def to_number(v):
    if v is None:
        return 0
    if isinstance(v, bool):
        return 1 if v else 0
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        try:
            if '.' in v:
                return float(v)
            return int(v)
        except Exception:
            # Try parsing date
            try:
                return int(datetime.strptime(v, '%Y-%m-%d %H:%M:%S').timestamp())
            except Exception:
