    if name in ('contains_kanji', 'kanji'):
        return any(0x4E00 <= ord(c) <= 0x9FFF for c in to_string(args[0]))
    if name in ('contains_greek', 'greek'):
        return any(0x0370 <= ord(c) <= 0x03FF for c in to_string(args[0]))
    return None


def extract_date_part(val, part):
    s = to_string(val)
    dt = None
    for f in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d'):
        try:
            dt = datetime.strptime(s, f)
            break
        except Exception:
            continue
    if dt is None:
        try:
            dt = datetime.fromtimestamp(int(to_number(val)))
        except Exception:
            return 0
    if part == 'year': return dt.year
    if part == 'month': return dt.month
    if part == 'day': return dt.day
    if part == 'hour': return dt.hour
    if part == 'minute': return dt.minute
    if part == 'second': return dt.second
    if part == 'dow':
        # 1-7, Sunday is 1
        return (dt.weekday() + 1) % 7 + 1
    if part == 'weekday':
        return dt.strftime('%A')
    if part == 'doy':
        return int(dt.strftime('%j'))
    if part == 'week':
        return int(dt.strftime('%W'))
    return 0
