# ---------------------------------------------------------------------------
# File traversal
# ---------------------------------------------------------------------------

def walk_root(root, cfg):
    """Yield records for files under root honouring path options.
    Each record: {'path': rel_path_incl_root_basename_or_child,
                  'abspath': abs, 'root': root_info, 'stat': ..., 'lstat': ...}
    """
    root_path = root['path']
    # resolve path
    try:
        abs_root = os.path.realpath(root_path)
    except Exception:
        abs_root = root_path
    if not os.path.exists(abs_root):
        raise OSError(2, "No such file or directory", root_path)

    mindepth = root.get('mindepth', 0)
    maxdepth = root.get('maxdepth', 0)
    follow = root.get('symlinks', False)
    dfs = root.get('dfs', False)

    def stat_of(p):
        try:
            return os.stat(p, follow_symlinks=True)
        except Exception:
            try:
                return os.lstat(p)
            except Exception:
                return None

    def lstat_of(p):
        try:
            return os.lstat(p)
        except Exception:
            return None

    # Display of path: basename of root when referencing the root itself,
    # otherwise relative to the directory containing the root (matching the
    # original tool's behaviour).
    root_display = os.path.basename(root_path.rstrip('/')) if root_path not in ('.', './') else ''

    # Compute abspath of root and its parent so we can form 'path' relative.
    # The 'path' column expects a root-relative path, e.g. for root='.' and child 'a.txt' -> 'a.txt'
    # For root='/tmp/foo' and file '/tmp/foo/a.txt' -> 'a.txt'. (The first tests showed this.)
    def relpath(abs_p):
        if abs_p == abs_root:
            return ''
        return os.path.relpath(abs_p, abs_root)

    # Check whether the root itself should be considered at depth 0.
    # Tests suggest the root is emitted only if the root path is '.' and it lists the children directly.
    # When path is '.', we do not emit '.' as an entry, only its children.

    def emit(abs_p, depth):
        if mindepth and depth < mindepth:
            return None
        if maxdepth and depth > maxdepth:
            return None
        st = stat_of(abs_p)
        ls = lstat_of(abs_p)
        rel = relpath(abs_p)
        return {
            'path': rel,
            'abspath': abs_p,
            'root': root,
            'stat': st,
            'lstat': ls,
            'depth': depth,
        }

    # We always emit children of the root (not the root itself).
    if not os.path.isdir(abs_root):
        # single file
        rec = emit(abs_root, 0)
        if rec:
            yield rec
        return

    if dfs:
        def recur(dirpath, depth):
            try:
                entries = sorted(os.listdir(dirpath))
            except Exception as e:
                raise e
            for entry in entries:
                abs_p = os.path.join(dirpath, entry)
                is_symlink = os.path.islink(abs_p)
                rec = emit(abs_p, depth)
                if rec is not None:
                    yield rec
                # recurse into directories
                if os.path.isdir(abs_p) and (follow or not is_symlink):
                    if maxdepth and depth + 1 > maxdepth:
                        continue
                    yield from recur(abs_p, depth + 1)
        yield from recur(abs_root, 1)
    else:
        # BFS
        from collections import deque
        # First yield all direct children in sorted order, then descend
        queue = deque()
        queue.append((abs_root, 0))
        # Layered BFS: for each directory in queue, list its children in sorted order, emitting as we go.
        while queue:
            dirpath, depth = queue.popleft()
            try:
                entries = sorted(os.listdir(dirpath))
            except Exception:
                continue
            for entry in entries:
                abs_p = os.path.join(dirpath, entry)
                is_symlink = os.path.islink(abs_p)
                rec = emit(abs_p, depth + 1)
                if rec is not None:
                    yield rec
                if os.path.isdir(abs_p) and (follow or not is_symlink):
                    if maxdepth and depth + 2 > maxdepth:
                        continue
                    queue.append((abs_p, depth + 1))


# ---------------------------------------------------------------------------
# Output formatting
# ---------------------------------------------------------------------------

def column_title(expr_ast):
    """Derive a 'title' for a column expression (used for JSON/HTML headers)."""
    if expr_ast.kind == 'ident':
        return expr_ast.value.capitalize() if expr_ast.value.islower() else expr_ast.value
    if expr_ast.kind == 'call':
        return expr_ast.value
    if expr_ast.kind == 'string':
        return expr_ast.value
    if expr_ast.kind == 'number':
        return str(expr_ast.value)
    return ''


def stringify_value(v):
    if v is None:
        return ''
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, float):
        if v == int(v):
            return str(int(v))
        return repr(v)
    return str(v)


def format_output(rows, columns, fmt, raw_query):
    if fmt == 'tabs':
        out = []
        for r in rows:
            out.append('\t'.join(stringify_value(v) for v in r))
        return '\n'.join(out) + ('\n' if out else '')
    if fmt == 'lines':
        out = []
        for r in rows:
            for v in r:
                out.append(stringify_value(v))
        return '\n'.join(out) + ('\n' if out else '')
    if fmt == 'list':
        # NUL-separated
        parts = []
        for r in rows:
            for v in r:
                parts.append(stringify_value(v))
        return '\0'.join(parts) + ('\0' if parts else '')
    if fmt == 'csv':
        import csv
        import io
        buf = io.StringIO()
        w = csv.writer(buf, lineterminator='\n')
        for r in rows:
            w.writerow([stringify_value(v) for v in r])
        return buf.getvalue()
    if fmt == 'json':
        objs = []
        titles = [column_title(c) for c in columns]
        for r in rows:
            obj = {}
            for t, v in zip(titles, r):
                obj[t] = stringify_value(v)
            objs.append(obj)
        return jsonmod.dumps(objs, separators=(',', ':'), ensure_ascii=False)
    if fmt == 'html':
        ncols = len(columns)
        body = []
        body.append('<html><head><title>%s</title></head>' % raw_query)
        body.append('<body><table><tr><th colspan="%d">%s</th></tr>' % (ncols, raw_query))
        for r in rows:
            body.append('<tr>' + ''.join('<td>%s</td>' % stringify_value(v) for v in r) + '</tr>')
        body.append('</table></body></html>')
        return ''.join(body)
    # default tabs
    return format_output(rows, columns, 'tabs', raw_query)


# ---------------------------------------------------------------------------
# Main execution
# ---------------------------------------------------------------------------

def contains_aggregate(node):
    if node is None:
        return False
    if node.kind == 'call' and node.value in AGGREGATES:
        return True
    for c in node.children or []:
        if contains_aggregate(c):
            return True
    return False


def eval_row(ast, record, ctx):
    return eval_expr(ast, record, ctx)


def execute(query, cfg):
    columns = query['columns']
    roots = query['roots']
    if not roots:
        roots = [{'path': '.', 'mindepth': 0, 'maxdepth': 0,
                  'archives': False, 'symlinks': False, 'regexp': False,
                  'gitignore': None, 'hgignore': None, 'dockerignore': None,
                  'dfs': False, 'alias': None}]
    # collect matching records
    records = []
    for root in roots:
        try:
            for rec in walk_root(root, cfg):
                records.append(rec)
        except OSError as e:
            msg = "could not canonicalize path: %s (os error %s)" % (e.strerror or str(e), e.errno or '?')
            eprint(root['path'], msg, no_errors=cfg['no_errors'])
            continue

    # filter with where clause
    ctx = {}
    if query['where'] is not None:
        records = [r for r in records if eval_truthy(query['where'], r, ctx)]

    # aggregate handling: if any selected column contains aggregate, collapse
    has_agg = any(contains_aggregate(c) for c in columns)

    if query['group_by']:
        # Group by specified columns
        groups = {}
        for r in records:
            key = tuple(stringify_value(eval_expr(g, r, ctx)) for g in query['group_by'])
            groups.setdefault(key, []).append(r)
        rows = []
        for key, recs in groups.items():
            row = []
            for c in columns:
                row.append(eval_with_aggregate(c, recs, ctx))
            rows.append(row)
    elif has_agg:
        # All columns compute over the whole record set (or 0 records)
        row = [eval_with_aggregate(c, records, ctx) for c in columns]
        rows = [row]
    else:
        rows = []
        for r in records:
            row = [eval_expr(c, r, ctx) for c in columns]
            rows.append(row)

    # order by
    if query['order_by']:
        def keyfn(row_tuple):
            r, orig_rec = row_tuple
            keys = []
            for expr, direction in query['order_by']:
                if expr.kind == 'number':
                    try:
                        idx = int(parse_number_token(expr.value)) - 1
                        val = r[idx] if 0 <= idx < len(r) else ''
                    except Exception:
                        val = 0
                else:
                    val = eval_expr(expr, orig_rec, ctx) if orig_rec else ''
                keys.append(val)
            return keys
        if has_agg or query['group_by']:
            paired = [(row, None) for row in rows]
        else:
            paired = list(zip(rows, records))
        # Multi-key sort with direction
        def sort_cmp_key(rt):
            ks = keyfn(rt)
            normalized = []
            for k in ks:
                if isinstance(k, bool):
                    normalized.append((0, int(k)))
                elif isinstance(k, (int, float)):
                    normalized.append((1, k))
                else:
                    normalized.append((2, to_string(k)))
            return normalized
        paired.sort(key=sort_cmp_key)
        # apply desc by reversing when all directions are desc; otherwise multi-pass stable sort
        directions = [d for _, d in query['order_by']]
        if any(d == 'desc' for d in directions):
            # Stable multi-pass in reverse priority
            for i in range(len(directions) - 1, -1, -1):
                direction = directions[i]
                rev = (direction == 'desc')
                expr = query['order_by'][i][0]

                def k_of(rt, idx=i):
                    r, orig = rt
                    ex = query['order_by'][idx][0]
                    if ex.kind == 'number':
                        try:
                            ci = int(parse_number_token(ex.value)) - 1
                            val = r[ci] if 0 <= ci < len(r) else ''
                        except Exception:
                            val = 0
                    else:
                        val = eval_expr(ex, orig, ctx) if orig else ''
                    if isinstance(val, bool):
                        return (0, int(val))
                    if isinstance(val, (int, float)):
                        return (1, val)
                    return (2, to_string(val))
                paired.sort(key=k_of, reverse=rev)
        rows = [r for r, _ in paired]

    # offset / limit
    if query['offset']:
        rows = rows[query['offset']:]
    if query['limit'] is not None and query['limit'] > 0:
        rows = rows[:query['limit']]

    return rows


def eval_with_aggregate(expr, records, ctx):
    if expr.kind == 'call' and expr.value in AGGREGATES:
        name = expr.value
        vals = []
        for r in records:
            if expr.children:
                vals.append(eval_expr(expr.children[0], r, ctx))
            else:
                vals.append(1)
        if name == 'count':
            return len(records) if not expr.children else sum(1 for v in vals if v is not None and to_string(v) != '')
        nums = [to_number(v) for v in vals if v is not None]
        if not nums:
            return 0
        if name == 'sum':
            return sum(nums)
        if name == 'min':
            return min(nums)
        if name == 'max':
            return max(nums)
        if name == 'avg':
            return sum(nums) / len(nums)
        if name in ('stddev_pop', 'stddev', 'std'):
            m = sum(nums) / len(nums)
            return math.sqrt(sum((x - m) ** 2 for x in nums) / len(nums))
        if name == 'stddev_samp':
            if len(nums) < 2:
                return 0
            m = sum(nums) / len(nums)
            return math.sqrt(sum((x - m) ** 2 for x in nums) / (len(nums) - 1))
        if name in ('var_pop', 'variance'):
            m = sum(nums) / len(nums)
            return sum((x - m) ** 2 for x in nums) / len(nums)
        if name == 'var_samp':
            if len(nums) < 2:
                return 0
            m = sum(nums) / len(nums)
            return sum((x - m) ** 2 for x in nums) / (len(nums) - 1)
    # non-aggregate: compute for the first record (or return '')
    if records:
        return eval_expr(expr, records[0], ctx)
    return ''


# ---------------------------------------------------------------------------
# Argument parsing / entry point
# ---------------------------------------------------------------------------

def print_help(full=True, color=True):
    if full:
        sys.stdout.write(make_full_help(color))
    else:
        sys.stdout.write(make_short_help(color))


def main(argv):
    args = argv[1:]
    color_enabled = not _colors_disabled()
    no_errors = False
    us_dates = False
    config_path = None
    interactive = False
    show_full_help = False
    show_short_help = False

    query_args = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('--help', '-h'):
            show_full_help = True
            i += 1
            continue
        if a in ('--nocolor', '--no-color'):
            color_enabled = False
            i += 1
            continue
        if a == '--no-errors':
            no_errors = True
            i += 1
            continue
        if a == '--us-dates':
            us_dates = True
            i += 1
            continue
        if a == '--config':
            config_path = args[i+1] if i + 1 < len(args) else None
            i += 2
            continue
        if a in ('--interactive', '-i'):
            interactive = True
            i += 1
            continue
        if a.startswith('--') and len(a) > 2 and a != '--':
            # unknown -- long option: pass to query parser (will fail with comment)
            query_args.append(a)
            i += 1
            continue
        if a.startswith('-') and len(a) > 1 and not a[1].isdigit() and a != '-':
            # Short prefix like -help: treat as help
            if 'help'.startswith(a[1:]):
                show_full_help = True
                i += 1
                continue
        query_args.append(a)
        i += 1

    cfg = {
        'color': color_enabled,
        'no_errors': no_errors,
        'us_dates': us_dates,
        'config_path': config_path,
    }

    if show_full_help:
        print_help(True, color_enabled)
        return 0

    if interactive:
        return run_interactive(cfg)

    if not query_args:
        print_help(False, color_enabled)
        return 0

    raw = ' '.join(query_args)
    try:
        q = parse_query(raw)
    except ParseError as e:
        eprint('query', str(e))
        return 2
    try:
        rows = execute(q, cfg)
    except Exception as e:
        eprint('query', str(e), no_errors=no_errors)
        return 1

    out = format_output(rows, q['columns'], q['format'], raw)
    sys.stdout.write(out)
    return 0


def run_interactive(cfg):
    try:
        while True:
            try:
                line = input('> ')
            except EOFError:
                sys.stdout.write('\n')
                break
            line = line.strip()
            if not line:
                continue
            low = line.lower()
            if low in ('quit', 'exit'):
                break
            if low == 'help':
                sys.stdout.write(make_full_help(cfg['color']))
                continue
            if low == 'pwd':
                sys.stdout.write(os.getcwd() + '\n')
                continue
            if low.startswith('cd '):
                try:
                    os.chdir(line[3:].strip())
                except Exception as e:
                    sys.stdout.write('error: %s\n' % e)
                continue
            if low.startswith('errors '):
                v = low[len('errors '):].strip()
                cfg['no_errors'] = (v == 'off')
                continue
            try:
                q = parse_query(line)
            except ParseError as e:
                eprint('query', str(e))
                continue
            try:
                rows = execute(q, cfg)
                sys.stdout.write(format_output(rows, q['columns'], q['format'], line))
            except Exception as e:
                eprint('query', str(e), no_errors=cfg['no_errors'])
    except KeyboardInterrupt:
        sys.stdout.write('\n')
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))
