def format_output(rows, columns, fmt, raw_query):
    if fmt == 'tabs':
        out = []
        for r in rows:
            out.append('\t'.join(stringify_value(v) for v in r))
        return '\n'.join(out) + ('\n' if out else '')
    if fmt == 'lines':
        out = []
        for r in rows:
            for v in r:
                out.append(stringify_value(v))
        return '\n'.join(out) + ('\n' if out else '')
    if fmt == 'list':
        # NUL-separated
        parts = []
        for r in rows:
            for v in r:
                parts.append(stringify_value(v))
        return '\0'.join(parts) + ('\0' if parts else '')
    if fmt == 'csv':
        import csv
        import io
        buf = io.StringIO()
        w = csv.writer(buf, lineterminator='\n')
        for r in rows:
            w.writerow([stringify_value(v) for v in r])
        return buf.getvalue()
    if fmt == 'json':
        objs = []
        titles = [column_title(c) for c in columns]
        for r in rows:
            obj = {}
            for t, v in zip(titles, r):
                obj[t] = stringify_value(v)
            objs.append(obj)
        return jsonmod.dumps(objs, separators=(',', ':'), ensure_ascii=False)
    if fmt == 'html':
        ncols = len(columns)
        body = []
        body.append('<html><head><title>%s</title></head>' % raw_query)
        body.append('<body><table><tr><th colspan="%d">%s</th></tr>' % (ncols, raw_query))
        for r in rows:
