    ctx = {}
    if query['where'] is not None:
        records = [r for r in records if eval_truthy(query['where'], r, ctx)]

    # aggregate handling: if any selected column contains aggregate, collapse
    has_agg = any(contains_aggregate(c) for c in columns)

    if query['group_by']:
        # Group by specified columns
        groups = {}
        for r in records:
            key = tuple(stringify_value(eval_expr(g, r, ctx)) for g in query['group_by'])
            groups.setdefault(key, []).append(r)
        rows = []
        for key, recs in groups.items():
            row = []
            for c in columns:
                row.append(eval_with_aggregate(c, recs, ctx))
            rows.append(row)
    elif has_agg:
        # All columns compute over the whole record set (or 0 records)
        row = [eval_with_aggregate(c, records, ctx) for c in columns]
        rows = [row]
    else:
        rows = []
        for r in records:
            row = [eval_expr(c, r, ctx) for c in columns]
            rows.append(row)

    # order by
    if query['order_by']:
        def keyfn(row_tuple):
            r, orig_rec = row_tuple
            keys = []
            for expr, direction in query['order_by']:
                if expr.kind == 'number':
                    try:
                        idx = int(parse_number_token(expr.value)) - 1
                        val = r[idx] if 0 <= idx < len(r) else ''
                    except Exception:
                        val = 0
                else:
                    val = eval_expr(expr, orig_rec, ctx) if orig_rec else ''
                keys.append(val)
            return keys
        if has_agg or query['group_by']:
            paired = [(row, None) for row in rows]
        else:
            paired = list(zip(rows, records))
        # Multi-key sort with direction
        def sort_cmp_key(rt):
            ks = keyfn(rt)
            normalized = []
            for k in ks:
                if isinstance(k, bool):
                    normalized.append((0, int(k)))
                elif isinstance(k, (int, float)):
                    normalized.append((1, k))
                else:
                    normalized.append((2, to_string(k)))
            return normalized
        paired.sort(key=sort_cmp_key)
        # apply desc by reversing when all directions are desc; otherwise multi-pass stable sort
        directions = [d for _, d in query['order_by']]
        if any(d == 'desc' for d in directions):
            # Stable multi-pass in reverse priority
            for i in range(len(directions) - 1, -1, -1):
                direction = directions[i]
                rev = (direction == 'desc')
                expr = query['order_by'][i][0]

                def k_of(rt, idx=i):
                    r, orig = rt
                    ex = query['order_by'][idx][0]
                    if ex.kind == 'number':
                        try:
                            ci = int(parse_number_token(ex.value)) - 1
                            val = r[ci] if 0 <= ci < len(r) else ''
                        except Exception:
                            val = 0
                    else:
