    if query['limit'] is not None and query['limit'] > 0:
        rows = rows[:query['limit']]

    return rows


def eval_with_aggregate(expr, records, ctx):
    if expr.kind == 'call' and expr.value in AGGREGATES:
        name = expr.value
        vals = []
        for r in records:
            if expr.children:
                vals.append(eval_expr(expr.children[0], r, ctx))
            else:
                vals.append(1)
        if name == 'count':
            return len(records) if not expr.children else sum(1 for v in vals if v is not None and to_string(v) != '')
        nums = [to_number(v) for v in vals if v is not None]
        if not nums:
            return 0
        if name == 'sum':
            return sum(nums)
        if name == 'min':
            return min(nums)
        if name == 'max':
            return max(nums)
        if name == 'avg':
            return sum(nums) / len(nums)
        if name in ('stddev_pop', 'stddev', 'std'):
            m = sum(nums) / len(nums)
            return math.sqrt(sum((x - m) ** 2 for x in nums) / len(nums))
        if name == 'stddev_samp':
            if len(nums) < 2:
                return 0
            m = sum(nums) / len(nums)
            return math.sqrt(sum((x - m) ** 2 for x in nums) / (len(nums) - 1))
        if name in ('var_pop', 'variance'):
            m = sum(nums) / len(nums)
            return sum((x - m) ** 2 for x in nums) / len(nums)
        if name == 'var_samp':
            if len(nums) < 2:
                return 0
            m = sum(nums) / len(nums)
            return sum((x - m) ** 2 for x in nums) / (len(nums) - 1)
    # non-aggregate: compute for the first record (or return '')
    if records:
        return eval_expr(expr, records[0], ctx)
    return ''


