def print_help(full=True, color=True):
    if full:
        sys.stdout.write(make_full_help(color))
    else:
        sys.stdout.write(make_short_help(color))


def main(argv):
    args = argv[1:]
    color_enabled = not _colors_disabled()
    no_errors = False
    us_dates = False
    config_path = None
    interactive = False
    show_full_help = False
    show_short_help = False

    query_args = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ('--help', '-h'):
            show_full_help = True
            i += 1
            continue
        if a in ('--nocolor', '--no-color'):
            color_enabled = False
            i += 1
            continue
        if a == '--no-errors':
            no_errors = True
            i += 1
            continue
        if a == '--us-dates':
            us_dates = True
            i += 1
            continue
        if a == '--config':
            config_path = args[i+1] if i + 1 < len(args) else None
            i += 2
            continue
        if a in ('--interactive', '-i'):
            interactive = True
            i += 1
            continue
        if a.startswith('--') and len(a) > 2 and a != '--':
            # unknown -- long option: pass to query parser (will fail with comment)
            query_args.append(a)
            i += 1
            continue
        if a.startswith('-') and len(a) > 1 and not a[1].isdigit() and a != '-':
            # Short prefix like -help: treat as help
            if 'help'.startswith(a[1:]):
                show_full_help = True
                i += 1
                continue
        query_args.append(a)
        i += 1

    cfg = {
        'color': color_enabled,
        'no_errors': no_errors,
        'us_dates': us_dates,
        'config_path': config_path,
    }

    if show_full_help:
        print_help(True, color_enabled)
        return 0

    if interactive:
        return run_interactive(cfg)

    if not query_args:
        print_help(False, color_enabled)
        return 0

    raw = ' '.join(query_args)
    try:
        q = parse_query(raw)
    except ParseError as e:
        eprint('query', str(e))
        return 2
    try:
        rows = execute(q, cfg)
    except Exception as e:
        eprint('query', str(e), no_errors=no_errors)
        return 1

    out = format_output(rows, q['columns'], q['format'], raw)
    sys.stdout.write(out)
    return 0


def run_interactive(cfg):
    try:
        while True:
            try:
                line = input('> ')
            except EOFError:
                sys.stdout.write('\n')
                break
            line = line.strip()
            if not line:
                continue
            low = line.lower()
            if low in ('quit', 'exit'):
                break
            if low == 'help':
                sys.stdout.write(make_full_help(cfg['color']))
                continue
            if low == 'pwd':
                sys.stdout.write(os.getcwd() + '\n')
                continue
            if low.startswith('cd '):
                try:
                    os.chdir(line[3:].strip())
                except Exception as e:
                    sys.stdout.write('error: %s\n' % e)
                continue
            if low.startswith('errors '):
                v = low[len('errors '):].strip()
                cfg['no_errors'] = (v == 'off')
                continue
            try:
                q = parse_query(line)
            except ParseError as e:
                eprint('query', str(e))
                continue
            try:
                rows = execute(q, cfg)
                sys.stdout.write(format_output(rows, q['columns'], q['format'], line))
            except Exception as e:
                eprint('query', str(e), no_errors=cfg['no_errors'])
    except KeyboardInterrupt:
        sys.stdout.write('\n')
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))
